import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"基准测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/benchmarking.md","filePath":"zh-Hans/deep-dive/benchmarking.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/benchmarking.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="基准测试" tabindex="-1">基准测试 <a class="header-anchor" href="#基准测试" aria-label="Permalink to “基准测试”">​</a></h1><h2 id="基准测试标准" tabindex="-1">基准测试标准 <a class="header-anchor" href="#基准测试标准" aria-label="Permalink to “基准测试标准”">​</a></h2><p>基准测试旨在获得 Sync Engine 与其他同步插件之间可靠、可复现的同步性能与算法正确性统计。测试期间 Obsidian 实例只能安装被测插件。被测插件必须使用默认设置，以下情况除外：</p><ul><li>账户配置</li><li>阻止同步非交互式进行的 UI 确认</li><li>会导致最终结果出现<a href="#正确性验证器">正确性验证器</a>意义上的&quot;错误&quot;的设置（大小上限 / 不同步特定文件 / ...）</li></ul><p>每次基准测试都包含下述固定流程和测试用例，任何对测试流程的特殊偏离都必须清楚记录。</p><h3 id="基准测试签名" tabindex="-1">基准测试签名 <a class="header-anchor" href="#基准测试签名" aria-label="Permalink to “基准测试签名”">​</a></h3><p>为确保可复现性，每次基准测试必须包含以下元数据：</p><ul><li>被测插件</li><li>Obsidian 版本</li><li>被测插件版本</li><li>测试机的操作系统（由于测试脚本的假设，不支持 Windows）</li><li>测试机的 Geekbench 7 CPU 单核跑分（可在 <a href="https://browser.geekbench.com/" target="_blank" rel="noreferrer">Geekbench 网站</a>搜索并估算平均值）</li><li>被测远端后端类型与服务</li><li>到被测服务的平均 ping 延迟（毫秒），使用 <a href="#ping-测试器">Ping 测试器</a></li><li>被测服务的平均上传与下载速度（MiB/s）</li></ul><h3 id="概览统计" tabindex="-1">概览统计 <a class="header-anchor" href="#概览统计" aria-label="Permalink to “概览统计”">​</a></h3><p><strong>插件体积</strong>：从对应版本的 GitHub 发布页获取。</p><p><strong>透明</strong>：作者是否让每个可控组件保持透明。</p><p><strong>启动速度</strong>：</p><p>在测试机上彻底杀掉 Obsidian Electron 应用并重启 5 次，每次记录 Obsidian 设置 -&gt; General -&gt; Advanced -&gt; Notify if startup takes longer than expected -&gt; 秒表图标 -&gt; 被测插件的启动时间（毫秒）。然后取 5 次记录的平均值。</p><p><strong>同步隐藏文件</strong>：插件能否（或能否配置为）同步以 <code>.</code> 开头的文件夹中的任意文件。例如 <code>.obsidian/</code> 目录。（Obsidian 的 <code>vault.*</code> API 看不到这些文件，只有 <code>vault.adapter.*</code> 可以）</p><p><strong>移动检测</strong>：插件能否正确识别本地和远端的文件移动，而不是把它们变成删除 + 上传 / 下载。</p><p><strong>分块传输</strong>：插件读 / 写 / 下载 / 上传大文件时是否使用流或分块，不在内存中缓冲整个文件。这个特性决定了它能否在移动设备上传输大文件而不崩溃。</p><p><strong>元数据同步</strong>：插件能否在跨设备同步时保留文件的最后修改时间 / 创建时间。</p><p><strong>加密</strong>：插件是否支持客户端加密。</p><p><strong>冲突解决</strong>：文件在本地和远端同时被修改时，解决冲突所用的方法。</p><h3 id="测试用例" tabindex="-1">测试用例 <a class="header-anchor" href="#测试用例" aria-label="Permalink to “测试用例”">​</a></h3><p><strong>上传速度</strong>：</p><p>用<a href="#测试仓库引导器">测试仓库引导器</a>初始化一个确定性的测试仓库。</p><p>然后用被测插件发起一次非交互式同步，等待完成，取插件的总同步时长。</p><p><strong>下载速度</strong>：</p><p>复用上面已上传的测试仓库，新建一个空仓库并配置被测插件。执行全量同步从远端下载这些文件，记录时长。</p><p><strong>日常同步速度</strong></p><p>此时应有两份仓库：一份（原始库）由<a href="#测试仓库引导器">测试仓库引导器</a>生成，另一份（副本库）是从远端新下载的。</p><p>在原始库中用<a href="#操作执行器">操作执行器</a>执行确定性的变更即同步。脚本包含 10 个独立、顺序执行的测试用例，覆盖创建、修改、删除和重命名（移动）操作，模拟规模小但频繁的用户编辑。每个操作由 CLI 命令放行以继续。每个用例先在原始库触发一次同步，再在副本库触发一次。如果被测插件有 &quot;Sync on change&quot; 选项，在原始库中启用它；否则在原始库手动触发同步。</p><p>全部用例完成后，计算上述 10 次同步的最大、最小和中位时长。</p><p><strong>同步正确性</strong>：</p><p>对原始库和副本库都运行<a href="#正确性验证器">正确性验证器</a>，把每个库出现的错误总数加总。它代表插件的稳定性和可靠性。</p><h2 id="基准测试工具" tabindex="-1">基准测试工具 <a class="header-anchor" href="#基准测试工具" aria-label="Permalink to “基准测试工具”">​</a></h2><p>基准测试工具位于本仓库的 <code>scripts/benchmark/</code>。它是一个主要与 Obsidian CLI 交互的 CLI 应用，包含五个模块：测试仓库引导器、操作执行器、正确性验证器和 Ping 测试器。</p><h3 id="测试仓库引导器" tabindex="-1">测试仓库引导器 <a class="header-anchor" href="#测试仓库引导器" aria-label="Permalink to “测试仓库引导器”">​</a></h3><p>文件：<code>scripts/benchmark/test-vault.ts</code></p><p>用 <code>scripts/benchmark/test-vault.ts</code> 初始化一个确定性的测试仓库。它先清空仓库，然后用一个随机深层嵌套文件的大型仓库模拟填充仓库：1880 个 50 字节到 50 KiB 的小文件，100 个 500 KiB 到 2 MiB 的中等文件，以及 20 个 15 MiB 到 100 MiB 的大文件。</p><h3 id="操作执行器" tabindex="-1">操作执行器 <a class="header-anchor" href="#操作执行器" aria-label="Permalink to “操作执行器”">​</a></h3><p>文件：<code>scripts/benchmark/daily-test.ts</code></p><p>操作执行器以串行或并行方式执行预定义的命令操作，它遵循声明式语法遍历一个 <code>Commands</code> 数组：</p><div class="language-TypeScript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">TypeScript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MaybePromise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Command</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">	|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">	|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">command</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">callback</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> $</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ShellPromise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MaybePromise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; };</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Commands</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Command</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&gt;;</span></span></code></pre></div><p>命令数组中嵌套子数组里的所有命令并发执行。</p><p>命令通过执行 Obsidian CLI 命令挂接到运行中的 Obsidian 实例：</p><ul><li><code>obsidian create path=&lt;path&gt; content=&lt;content&gt; overwrite</code></li><li><code>obsidian delete path=&lt;path&gt;</code></li><li><code>obsidian move path=&lt;path&gt; to=&lt;destination&gt;</code></li></ul><p>日常测试流程包含 10 个测试用例，串行执行以模拟规模小但频繁的用户编辑。被测插件需要为每个测试用例执行一次同步。每次同步的时长都会被测量用于评估。</p><h3 id="正确性验证器" tabindex="-1">正确性验证器 <a class="header-anchor" href="#正确性验证器" aria-label="Permalink to “正确性验证器”">​</a></h3><p>文件：<code>scripts/benchmark/validator.ts</code></p><p>验证器用于在<a href="#操作执行器">操作执行器</a>执行完操作集合并完成后续同步之后，验证同步的正确性。它扫描一个仓库，校验每个文件和文件夹是否存在，缺失或多出的都标记为错误。对测试用例中追加过的文件，它还额外校验文件大小。</p><p>校验之后，它输出错误总数，以及每个错误及其原因。</p><h3 id="ping-测试器" tabindex="-1">Ping 测试器 <a class="header-anchor" href="#ping-测试器" aria-label="Permalink to “Ping 测试器”">​</a></h3><p>文件：<code>scripts/benchmark/ping-test.ts</code></p><p>Ping 测试器测试连接一个 URL 时的平均 HTTP ping 延迟。它向目标发起 20 个顺序的 HTTP <code>HEAD</code> 请求并记录响应延迟。</p><p>全部测试结束后，它对请求延迟排序，丢弃最长的两个和最短的两个，然后对剩余 16 个样本计算平均值。</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};